// #51da2a (b28a22ed6a85bb764151da2a) — плашка «החיבור חלש» по реальному ухудшению, а не по обычному RTT ~450 мс.
// Кейсы CQ-002, CQ-003. БЕЗ ЗВОНКА: старт попытки, голосовая сессия, обмен SDP, загрузка записи, события и конец
// попытки подменены (route.fulfill), RTCPeerConnection — подделка с управляемым getStats. OpenAI и официальная попытка
// не тратятся (api.openai.com — обрыв + проверка счётчика = 0).
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CQ-MOCK-…» (link_only), не удаляется (правило проекта).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, launchCandidate, goToPractice, goToOfficialConfirm, tap, timerSeconds } from '../candidate-call/support';
import {
  WARNING, LIVE_STATUS, warningBanner, watchWarning, warningStats, trackWarningEvents, fakePeer, mockCallBackend, setNet,
  statsCalls, expectLive, waitSamples, Net,
} from './support';

const HASH = '#b28a22ed6a85bb764151da2a';

/** business → кандидат со ссылкой; кандидат с подменами → экран звонка «live». */
async function openMockedCall(asUser: (id: string) => Promise<import('@playwright/test').Page>, tag: string, net: Net) {
  const business = await asUser('business');
  const name = `QA-AUTO-CQ-MOCK-${tag}-${runStamp()}`;
  const link = await createCandidateLink(business, name);
  test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (официальная попытка НЕ использована — старт подменён), не удаляется` });

  const cand = await launchCandidate({ width: 390, height: 844 });
  await watchWarning(cand.ctx);
  await fakePeer(cand.ctx, net);
  const page = cand.page;
  const events = trackWarningEvents(page);
  const mocked = await mockCallBackend(page);
  await goToPractice(page, link);
  await goToOfficialConfirm(page);
  await tap(page, 'מוכן, מתחילים');
  await expectLive(page);
  expect(mocked.start, 'candidate_start_attempt (подменённый)').toBe(1);
  expect(mocked.voice, 'start-voice-session (подменённый)').toBe(1);
  expect(mocked.sdp, 'обмен SDP (подменённый)').toBe(1);
  return { cand, page, events, mocked };
}

test.describe(`Звонок — плашка слабого соединения, логика без звонка (${HASH})`, () => {
  test(`RTT 450 мс, буфер 100 мс, потерь 0 (delay_ms 325): ≥ 8 замеров — плашки нет, connection_warning не отправлялся, звонок «live» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const { cand, page, events, mocked } = await openMockedCall(asUser, 'RTT450', { rttMs: 450, jbMs: 100, lossPct: 0 });
    try {
      // Окно монитора 10 с при замере раз в 2 с — 8 замеров покрывают его целиком с запасом.
      await waitSamples(page, await statsCalls(page), 8);

      // Источник: «מצב נוכחי» — «מסלול של כ-450 מ״ש … הוא רגיל»; AC «שיחה תקינה … ובלי התרעת חיבור קבועה».
      const w = await warningStats(page);
      expect(w.count, 'плашка «החיבור חלש» появлялась при RTT 450 мс').toBe(0);
      await expect(warningBanner(page)).toHaveCount(0);
      expect(events, 'candidate_record_event connection_warning при RTT 450 мс').toEqual([]);
      await expectLive(page);
      expect(mocked.ended, 'звонок не должен завершаться').toBe(0);
      expect(mocked.openai, 'запросы к OpenAI').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });

  test(`потери 25 % → плашка, звонок продолжается; потери 0 → плашка снята; RTT 800 мс (delay_ms 440) → плашка снова @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(5 * 60_000);
    const { cand, page, events, mocked } = await openMockedCall(asUser, 'LOSS', { rttMs: 150, jbMs: 40, lossPct: 0 });
    try {
      // Нормальная сеть сначала: плашки нет.
      await waitSamples(page, await statsCalls(page), 5);
      expect((await warningStats(page)).count, 'плашка на нормальной сети (RTT 150, потерь 0)').toBe(0);

      // Источник: «מצב נדרש» — «התרעת החיבור מופיעה רק כשאיכות הקול באמת יורדת (אובדן מנות מעל 20 אחוז …)»; Figma 866:10417.
      await setNet(page, { lossPct: 25 });
      const banner = warningBanner(page);
      await expect(banner).toBeVisible({ timeout: 30_000 });
      await expect(banner).toHaveText(WARNING);
      await expect(banner).toHaveAttribute('role', 'alert');
      await expect.poll(() => events.length, { message: 'нет candidate_record_event connection_warning' }).toBe(1);
      expect(Number(events[0].packet_loss), 'packet_loss в событии').toBeGreaterThan(0.2);

      // Источник: F-32 AC «…מוצגת לי התרעה על מצב החיבור והשיחה ממשיכה כל עוד ניתן»; FL-32 ш.1 «התרעה לא חוסמת».
      const t0 = await timerSeconds(page);
      await expect.poll(() => timerSeconds(page), { message: 'таймер звонка остановился при плашке', timeout: 10_000 }).toBeLessThan(t0);
      await expect(page.getByRole('status').filter({ hasText: LIVE_STATUS })).toBeVisible();
      await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeEnabled();
      await expect(page.getByTestId('call-stage')).toHaveAttribute('data-phase', 'live');
      expect(mocked.ended, 'плашка не должна завершать звонок').toBe(0);

      // Сеть нормализовалась: плашка снимается (≤ 20 % плохих замеров в окне 10 с).
      await setNet(page, { lossPct: 0 });
      await expect(banner, 'плашка не снялась после возврата потерь к 0').toBeHidden({ timeout: 30_000 });
      await expectLive(page);

      // Источник: «…או השהיה מעל 400 מ״ש כפי שהתרחיש מגדיר» — delay_ms = 800/2 + 40 = 440.
      await setNet(page, { rttMs: 800, jbMs: 40 });
      await expect(banner, 'нет плашки при delay_ms 440').toBeVisible({ timeout: 30_000 });
      await expect.poll(() => events.length, { message: 'нет второго connection_warning' }).toBe(2);
      expect(Number(events[1].delay_ms), 'delay_ms во втором событии').toBeGreaterThan(400);
      await expectLive(page);
      expect(mocked.ended).toBe(0);
      expect(mocked.openai, 'запросы к OpenAI').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });
});
